def _security_upgrade() -> None:
    for table in TABLES:
        op.execute(f"ALTER TABLE {table} ENABLE ROW LEVEL SECURITY")
        op.execute(f"ALTER TABLE {table} FORCE ROW LEVEL SECURITY")
        op.execute(f'''
            CREATE POLICY tenant_isolation ON {table}
            USING (organisation_id = app_current_org())
            WITH CHECK (organisation_id = app_current_org())
        ''')

    op.execute('''
        -- Chart entries and measurements: never edited or deleted; the only change is
        -- recorded -> entered_in_error with a reason.
        CREATE FUNCTION entered_in_error_only() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                RAISE EXCEPTION '% rows cannot be deleted', TG_TABLE_NAME;
            END IF;
            IF OLD.status = 'recorded' AND NEW.status = 'entered_in_error'
               AND NEW.status_reason IS NOT NULL
               AND (to_jsonb(NEW) - 'status' - 'status_reason')
                   = (to_jsonb(OLD) - 'status' - 'status_reason') THEN
                RETURN NEW;
            END IF;
            RAISE EXCEPTION '% rows cannot be modified; mark entered in error', TG_TABLE_NAME;
        END $$;
        CREATE TRIGGER dental_chart_integrity BEFORE UPDATE OR DELETE ON dental_chart_entries
            FOR EACH ROW EXECUTE FUNCTION entered_in_error_only();
        CREATE TRIGGER physio_measurements_integrity BEFORE UPDATE OR DELETE
            ON physio_measurements FOR EACH ROW EXECUTE FUNCTION entered_in_error_only();

        -- Once a plan leaves draft (quotation issued), procedures and fees are frozen;
        -- only progress (done, cancelled, invoiced) may change, and an invoice link is final.
        CREATE FUNCTION dental_plan_items_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        DECLARE plan_status text;
        BEGIN
            SELECT status INTO plan_status FROM dental_treatment_plans
                WHERE id = COALESCE(OLD.plan_id, NEW.plan_id);
            IF TG_OP = 'DELETE' THEN
                IF plan_status <> 'draft' THEN
                    RAISE EXCEPTION 'items of a proposed treatment plan cannot be deleted';
                END IF;
                RETURN OLD;
            END IF;
            IF OLD.invoice_id IS NOT NULL AND NEW.invoice_id IS DISTINCT FROM OLD.invoice_id THEN
                RAISE EXCEPTION 'an invoiced treatment item cannot be re-invoiced';
            END IF;
            IF plan_status <> 'draft'
               AND (to_jsonb(NEW) - 'status' - 'done_at' - 'done_encounter_id' - 'invoice_id')
                   <> (to_jsonb(OLD) - 'status' - 'done_at' - 'done_encounter_id' - 'invoice_id')
            THEN
                RAISE EXCEPTION 'quoted treatment items cannot be changed';
            END IF;
            RETURN NEW;
        END $$;
        CREATE TRIGGER dental_plan_items_integrity BEFORE UPDATE OR DELETE ON dental_plan_items
            FOR EACH ROW EXECUTE FUNCTION dental_plan_items_guard();

        CREATE FUNCTION no_delete() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN RAISE EXCEPTION '% rows cannot be deleted', TG_TABLE_NAME; END $$;
        CREATE TRIGGER dental_plans_no_delete BEFORE DELETE ON dental_treatment_plans
            FOR EACH ROW EXECUTE FUNCTION no_delete();

        CREATE FUNCTION physio_episodes_guard() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN
            IF TG_OP = 'DELETE' THEN
                RAISE EXCEPTION 'episodes of care cannot be deleted';
            END IF;
            IF OLD.status = 'discharged' THEN
                RAISE EXCEPTION 'a discharged episode of care cannot be changed';
            END IF;
            RETURN NEW;
        END $$;
        CREATE TRIGGER physio_episodes_integrity BEFORE UPDATE OR DELETE ON physio_episodes
            FOR EACH ROW EXECUTE FUNCTION physio_episodes_guard();

        CREATE FUNCTION specialty_append_only() RETURNS trigger LANGUAGE plpgsql AS $$
        BEGIN RAISE EXCEPTION '% is append-only', TG_TABLE_NAME; END $$;
        CREATE TRIGGER physio_sessions_append_only
            BEFORE UPDATE OR DELETE OR TRUNCATE ON physio_episode_sessions
            FOR EACH STATEMENT EXECUTE FUNCTION specialty_append_only();
    ''')

    role = get_settings().app_db_role
    op.execute(f'''
        DO $$
        BEGIN
            IF EXISTS (SELECT 1 FROM pg_roles WHERE rolname = '{role}') THEN
                GRANT SELECT, INSERT, UPDATE ON dental_chart_entries, dental_treatment_plans,
                    dental_plan_items, physio_episodes, physio_measurements TO {role};
                GRANT DELETE ON dental_plan_items TO {role};  -- draft plans only
                GRANT SELECT, INSERT ON physio_episode_sessions TO {role};
            END IF;
        END $$;
    ''')


